import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { NextResponse } from 'next/server';

export const runtime = 'nodejs';

const imageTypes: Record<string, string> = {
  jpg: 'image/jpeg',
  png: 'image/png',
  webp: 'image/webp',
};

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ filename: string }> },
) {
  const { filename } = await params;
  // Upload names are UUIDs generated by the server. Restrict the route to
  // that format so it cannot be used to read arbitrary files from disk.
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/i.test(filename)) {
    return new NextResponse('Image introuvable.', { status: 404 });
  }

  try {
    const bytes = await readFile(join(process.cwd(), 'data', 'uploads', 'cards', filename));
    return new Response(bytes, {
      headers: {
        'Content-Type': imageTypes[filename.split('.').at(-1)!.toLowerCase()],
        'Content-Length': String(bytes.byteLength),
        'Cache-Control': 'public, max-age=31536000, immutable',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  } catch {
    return new NextResponse('Image introuvable.', { status: 404 });
  }
}
